<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><section class="list-head"><div><p>Content assets</p><h1>Media library</h1></div></section><form class="upload-form" method="post" enctype="multipart/form-data" action="<?= site_url('admin/media') ?>"><?= csrf_field() ?><input type="file" name="file" accept="image/jpeg,image/png,image/webp" required><button class="primary">Upload image</button><span>JPG, PNG or WebP · 10 MB max</span></form><div class="media-grid"><?php foreach ($media as $item): ?><figure><img src="<?= esc($item['path']) ?>" alt=""><figcaption><strong><?= esc($item['filename']) ?></strong><code><?= esc($item['path']) ?></code></figcaption></figure><?php endforeach ?><?php if (! $media): ?><p>No uploaded images yet. Legacy images are available in <code>/assets/media/</code>.</p><?php endif ?></div><?= $this->endSection() ?>
